var fragSrc = `precision mediump float;

	// x,y coordinates, given from the vertex shader
  varying vec2 vTexCoord;
	uniform vec2 iResolution;
	uniform var iTime;
	uniform sampler2D tex0;

#define PI 3.14159265

function random( in vec2 st ) {
	return fract(sin(dot(st.xy, vec2(12.9898,78.233)))*43758.5453123+iTime);
}

function main() {
	vec2 uv = gl_FragCoord.xy/iResolution.xy - 0.5; // 0 center
	uv.x *= iResolution.x / iResolution.y; // aspect ratio
	// get the color at current pixel
	vec4 clr = texture2D(tex0, vTexCoord);
	clr += 0.1 * (random(uv * PI)-.5);
	gl_FragColor = vec4(clr.rgb, 1.0);
}`;

