var shGrain;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
  describe('display blocks of lines forming lines, maybe overlapping');
	frameRate(60);
	shGrain = createFilterShader(fragSrc);
}

function draw() {
	if (frameCount === 1 || frameCount % 120 === 0)	{
		background(216);
		// blocks
		drawBlock()
		if (random() < 0.7) drawBlock()
		if (random() < 0.4) drawBlock()
		if (random() < 0.1) drawBlock()
		// grain
		shGrain.setUniform('iResolution', [width * displayDensity(), height * displayDensity()]);
		shGrain.setUniform("iTime", millis()/1000);
		// shGrain.setUniform('tex1', get(0, 0, width, height));
		filter(shGrain);
	}
} // draw();

function drawBlock() {	
	stroke(random([16, 24, 32, "navy", "darkred"]));
	const ww = random(0.6, 0.95);
	const hh = random(0.02, 0.2);
	push()
	const minWH = max(width, height);
	const f = 0.2;
	translate(random(-width*f, width*f), random(-height*f, height*f))
	drawLines(width * (1-ww), height * (0.5-hh), width * ww, height * (0.5+hh))
	pop()
}

function drawLines(x1, y1, x2, y2) {
	for (let x = x1; x < x2;) {
		x += random(0.5, 3)
		drawVLine(x, y1, y2);
	}
}

function drawVLine(x, y1, y2) {
	strokeWeight(random(1, 3))
	// line(x1, y1, x2, y2)
	for (let y = y1; y < y2;) {
		y += random(0.5, 2)
		strokeWeight(random(1, 3))
		point(x, y);
	}
}
